  "bestCut.replace": "التطبيق يستبدل الخط الزمني للمشروع. التراجع يعيد الخط الزمني السابق.",
  "bestCut.consent": "للعثور على أفضل محاولة، تُرفع ملفات الفيديو المختارة كاملة إلى Veyrnox.ai وتُرسل إلى خدمة تفريغ كلام لقراءة الصوت. يبقى النص والملاحظات على هذا الهاتف. تُجدول عمليات رفع التفريغ المؤقتة للحذف بعد 24 ساعة؛ وقد يستغرق التنظيف وقتًا أطول. تُحفظ النصوص المفرغة حتى 30 يومًا لتجنب تحصيل الرسوم مرتين. حذف الحساب يحذف النصوص المفرغة. لنسخ المكتبة الأصلية والنسخ الاحتياطية للمشاريع دورة حفظ خاصة بها. إذا لم يتحدث أحد فلن تُفرض رسوم.",
  "bestCut.metadata": "لا يغادر الهاتف سوى الملفات المختارة ومدتها ونوعها ومعرّف حسابك ومفاتيح الطلبات. لا نحذف بيانات الموقع أو EXIF. لا يلزم إذن التعرف على الكلام في iOS.",
